923→// gitCommitWithShadowHooks is the shared implementation for committing with shadow hooks.
924→// When simulateTTY is true, sets ENTIRE_TEST_TTY=1 to simulate a human at the terminal.
925→// When false, filters it out to simulate an agent subprocess (no controlling terminal).
926→func (env *TestEnv) gitCommitWithShadowHooks(message string, simulateTTY bool, files ...string) {
927→	env.T.Helper()
928→
929→	// Stage files using go-git
930→	for _, file := range files {
931→		env.GitAdd(file)
932→	}
933→
934→	// Create a temp file for the commit message (prepare-commit-msg hook modifies this)
935→	msgFile := filepath.Join(env.RepoDir, ".git", "COMMIT_EDITMSG")
936→	if err := os.WriteFile(msgFile, []byte(message), 0o644); err != nil {
937→		env.T.Fatalf("failed to write commit message file: %v", err)
938→	}
939→
940→	// Run prepare-commit-msg hook using the shared binary.
941→	// Pass source="message" to match real `git commit -m` behavior.
942→	prepCmd := exec.Command(getTestBinary(), "hooks", "git", "prepare-commit-msg", msgFile, "message")
943→	prepCmd.Dir = env.RepoDir
944→	if simulateTTY {
945→		// Simulate human at terminal: ENTIRE_TEST_TTY=1 makes hasTTY() return true
946→		// and askConfirmTTY() return defaultYes without reading from /dev/tty.
947→		prepCmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=1")
948→	} else {
949→		// Simulate agent: ENTIRE_TEST_TTY=0 makes hasTTY() return false,
950→		// triggering the fast path that adds trailers for ACTIVE sessions.
951→		prepCmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
952→	}
953→	if output, err := prepCmd.CombinedOutput(); err != nil {
954→		env.T.Logf("prepare-commit-msg output: %s", output)
955→		// Don't fail - hook may silently succeed
956→	}
957→
958→	// Read the modified message
959→	modifiedMsg, err := os.ReadFile(msgFile)
960→	if err != nil {
961→		env.T.Fatalf("failed to read modified commit message: %v", err)
962→	}
963→
964→	// Create the commit using go-git with the modified message
965→	repo, err := git.PlainOpen(env.RepoDir)
966→	if err != nil {
967→		env.T.Fatalf("failed to open git repo: %v", err)
968→	}
969→
970→	worktree, err := repo.Worktree()
971→	if err != nil {
972→		env.T.Fatalf("failed to get worktree: %v", err)
973→	}
974→
975→	_, err = worktree.Commit(string(modifiedMsg), &git.CommitOptions{
976→		Author: &object.Signature{
977→			Name:  "Test User",
978→			Email: "test@example.com",
979→			When:  time.Now(),
980→		},
981→	})
982→	if err != nil {
983→		env.T.Fatalf("failed to commit: %v", err)
984→	}
985→
986→	// Run post-commit hook using the shared binary
987→	// This triggers condensation if the commit has an Entire-Checkpoint trailer
988→	postCmd := exec.Command(getTestBinary(), "hooks", "git", "post-commit")
989→	postCmd.Dir = env.RepoDir

